import type { Source, SourceArgs } from "./Core";
/**
 * Callbag operator that flattens another callbag source similar
 * to RxJS `switch`.
 *
 * Adapted from https://github.com/staltz/callbag-flatten
 *
 * @internal
 */
export declare const flatten: <T, E, OT extends Source<T, E>>(source: Source<OT, E>) => (...sourceArgs: OT extends Source<infer TT, infer EE> ? SourceArgs<TT, EE> : never) => void;
